import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

// n lines of `price` x 1
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

// issue #12, criterion 3: totals at discount rate 0 must stay as they were before the fix.
test('total at discount rate 0 is unchanged (issue #12)', () => {
  assert.equal(total(lines(9, 1000), 0), 9000);
  assert.equal(total(lines(10, 1000), 0), 9500);
  assert.equal(total(lines(10, 333), 0), 3164); // 3330 * 0.95 = 3163.5, rounded
});

// issue #12, criterion 1: the customer discount applies once.
test('customer discount applies once below 10 lines (issue #12)', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

// issue #12, criterion 2: customer discount first, then the 5% bulk discount once.
test('bulk discount applies once after the customer discount at 10 lines (issue #12)', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

// Boundary of criteria 1 and 2: 9 lines get the customer discount only.
test('no bulk discount at 9 lines with a customer discount (issue #12)', () => {
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});
